window.COURSE_GLOSSARY=[{"term": "Enterprise Brain", "aliases": ["enterprise brain"], "definition": "기업의 자료·의미·맥락을 재사용하는 시스템을 설명하는 넓은 표현입니다. 공급사의 제품명으로도 쓰이며, 이 교재에서는 수집·연결·근거·접근·변경을 묶는 작업 관점으로 사용합니다.", "lesson": "U01-L01"}, {"term": "Second Brain", "aliases": ["second brain"], "definition": "정보와 아이디어를 외부에 남겨 다시 사용하는 개인 지식 관리의 맥락입니다. Tiago Forte의 CODE·PARA는 그 방법론의 구체적인 흐름과 정리 방식입니다.", "lesson": "U01-L02"}, {"term": "Graph DB", "aliases": ["그래프 DB", "Graph DB"], "definition": "그래프 모델의 데이터와 연결을 저장·질의하는 DB 기술입니다. 그래프 그림·도메인 모델·Knowledge Graph와 역할이 다릅니다.", "lesson": "U02-L01"}, {"term": "Property Graph", "aliases": ["속성 그래프", "Property Graph", "property graph"], "definition": "노드와 관계를 중심으로 데이터를 표현하며 속성값을 함께 다루는 그래프 모델입니다. 라벨·타입·값·관계 규칙은 제품별 차이도 확인해야 합니다.", "lesson": "U03-L01"}, {"term": "Neo4j", "aliases": ["Neo4j"], "definition": "속성 그래프를 저장·질의하는 DBMS입니다. Cypher는 질의 언어이고 Browser 같은 도구는 질의와 결과를 다루는 화면입니다.", "lesson": "U03-L01"}, {"term": "Semantic Web", "aliases": ["Semantic Web"], "definition": "대상 식별자·관계·의미를 명시해 웹 데이터를 시스템 사이에서 공유하고 연결하는 방향입니다. Semantic HTML과 같은 층의 개념은 아닙니다.", "lesson": "U04-L01"}, {"term": "W3C", "aliases": ["W3C"], "definition": "웹 기술의 표준화 기구입니다. 해당 사이트의 문서도 Recommendation·Note·초안처럼 지위가 다르므로 상태와 판본을 함께 읽습니다.", "lesson": "U04-L01"}, {"term": "RDF", "aliases": ["RDF"], "definition": "식별된 대상에 대해 주어·술어·목적어 트리플로 진술을 표현하는 데이터 모델입니다. RDF 1.1 그래프는 트리플의 집합이며 Turtle·RDF/XML·JSON-LD 같은 구문과 구별합니다.", "lesson": "U04-L01"}, {"term": "Ontology", "aliases": ["온톨로지", "ontology", "Ontology"], "definition": "도메인에서 어떤 종류의 대상·관계·정의를 공유하며 어떤 가정을 적용할지 명시하는 의미 모델입니다. 데이터 필드 설계와 연결되지만 목적과 표현력이 항상 같은 것은 아닙니다.", "lesson": "U05-L01"}, {"term": "RDFS", "aliases": ["RDFS"], "definition": "클래스·속성·하위 관계·domain/range 등을 표현하는 RDF 어휘입니다. domain/range의 타입 추론을 필수 입력 검사로 읽지 않도록 주의합니다.", "lesson": "U06-L01"}, {"term": "OWL", "aliases": ["OWL"], "definition": "클래스·속성·개체에 관한 공리와 공식 의미를 제공하는 온톨로지 언어입니다. 동치·서로소·제한·동일성 등에서 어떤 결론이 따르는지 설명할 수 있습니다.", "lesson": "U06-L02"}, {"term": "SHACL", "aliases": ["SHACL"], "definition": "지정한 RDF 데이터와 모양(shape)에서 대상·값 개수·자료형 등의 조건을 검사하는 언어입니다. 검사 통과가 원문 충실성이나 실제 사실성의 증명은 아닙니다.", "lesson": "U06-L01"}, {"term": "Cypher", "aliases": ["Cypher"], "definition": "노드·관계 패턴을 사용해 속성 그래프를 질의하는 언어입니다. 이 교재는 MATCH·조건·반환·선택 패턴·집계의 결과 행을 읽는 수준을 다룹니다.", "lesson": "U07-L01"}, {"term": "SPARQL", "aliases": ["SPARQL"], "definition": "RDF 데이터의 패턴을 질의하는 언어입니다. 트리플 패턴에서 변수 바인딩을 찾고, 선택 패턴·집계·경로·그래프 범위에 따라 결과가 달라집니다.", "lesson": "U07-L01"}, {"term": "Knowledge Graph", "aliases": ["Knowledge Graph", "knowledge graph", "지식 그래프"], "definition": "대상과 관계를 의미·맥락과 함께 연결해 질문에 사용할 수 있게 한 지식 표현입니다. 단순 링크망·저장 제품·ontology와 구별하며 정의의 범위는 자료마다 다릅니다.", "lesson": "U08-L01"}, {"term": "Entity resolution", "aliases": ["entity resolution", "개체 정합"], "definition": "서로 다른 기록이 같은 실제 대상을 가리키는지 판단하고 연결하는 과정입니다. 문자열 정규화·유사도·DB 고유성 제약만으로 해결되지 않습니다.", "lesson": "U10-L01"}, {"term": "Auto ontology", "aliases": ["Auto ontology", "auto ontology", "ontology learning"], "definition": "자료에서 개념·관계·공리·매핑 등 모델 후보를 만들거나 확장하는 자동화입니다. 기존 모델에 개별 사실을 채우는 작업과 후보의 승인·운영 개정은 구별합니다.", "lesson": "U12-L01"}, {"term": "Vector RAG", "aliases": ["Vector RAG", "vector RAG"], "definition": "문서·질문 벡터의 유사도를 근거 검색에 이용하는 RAG 구성입니다. 필터·어휘 검색·재정렬·문맥 조립과 함께 필요한 근거가 실제 전달됐는지 확인합니다.", "lesson": "U13-L01"}, {"term": "RAG", "aliases": ["RAG"], "definition": "외부 자료를 검색해 생성 모델의 답변 근거로 사용하는 접근입니다. 원논문의 확률 결합 설계와 오늘날 여러 문단을 프롬프트에 넣는 구성을 구별해 읽습니다.", "lesson": "U13-L01"}, {"term": "Graph RAG", "aliases": ["Graph RAG", "graph RAG"], "definition": "그래프의 개체·관계·경로 등을 근거 검색에 활용하는 여러 구성입니다. Microsoft GraphRAG는 개체·관계와 커뮤니티 보고서를 만드는 특정 구현 계열입니다.", "lesson": "U14-L01"}, {"term": "Tree RAG", "aliases": ["Tree RAG", "tree RAG"], "definition": "문서나 요약의 계층을 검색에 활용하는 구성을 가리키는 표현입니다. 단순 문서 목차·parent-child 검색·재귀 요약 계층을 구별합니다.", "lesson": "U15-L01"}, {"term": "RAPTOR", "aliases": ["RAPTOR"], "definition": "청크 임베딩·군집·요약을 반복해 여러 추상화 수준의 정보를 검색하는 연구입니다. 층별 탐색과 여러 층을 함께 검색하는 방식을 비교합니다.", "lesson": "U15-L01"}];